using System;
using System.Collections.Generic;
class ConnectionTests {
 static SolidWorksSessionCandidate S(int pid,bool target,string version="33.1"){return new SolidWorksSessionCandidate{pid=pid,containsTarget=target,revision=version};}
 static bool Reject(IList<SolidWorksSessionCandidate> sessions,bool target){try{SolidWorksSessionPolicy.Choose(sessions,target);return false;}catch(InvalidOperationException){return true;}}
 static int Main(){if(SolidWorksSessionPolicy.Choose(new[]{S(10,false),S(20,true)},true).pid!=20)throw new Exception("Wrong instance");if(SolidWorksSessionPolicy.Choose(new[]{S(10,true),S(20,false)},true).pid!=10)throw new Exception("Enumeration order dependence");if(!Reject(new[]{S(10,true),S(20,true)},true))throw new Exception("Ambiguous model silently selected");if(!Reject(new[]{S(10,false)},true))throw new Exception("Absent model accepted");if(!Reject(new[]{S(10,false),S(20,false)},false))throw new Exception("Ambiguous active context accepted");if(SolidWorksSessionPolicy.Choose(new[]{S(10,false)},false).pid!=10)throw new Exception("Single existing instance rejected");if(!Reject(new[]{S(10,true,"34.0")},true))throw new Exception("Wrong SW version accepted");var empty=S(10,false);var faces=S(20,false);faces.hasSelectedPlanarFaces=true;if(SolidWorksSessionPolicy.Choose(new[]{empty,faces},false,true).pid!=20)throw new Exception("Face selection in second window ignored");if(SolidWorksSessionPolicy.Choose(new[]{faces,empty},false,true).pid!=20)throw new Exception("Face selection depends on order");var other=S(30,false);other.hasSelectedPlanarFaces=true;try{SolidWorksSessionPolicy.Choose(new[]{faces,other},false,true);throw new Exception("Ambiguous face selection accepted");}catch(InvalidOperationException ex){if(ex.Message!="FACES_SELECTION_AMBIGUOUS")throw;}try{SolidWorksSessionPolicy.Choose(new[]{empty,S(40,false)},false,true);throw new Exception("Missing faces accepted");}catch(InvalidOperationException ex){if(ex.Message!="FACES_SELECTION_NOT_FOUND")throw;}if(SolidWorksSessionPolicy.Choose(new[]{empty},false,true).pid!=10)throw new Exception("Single-window worker validation bypassed");var old=S(50,false,"32.0");old.hasSelectedPlanarFaces=true;if(SolidWorksSessionPolicy.Choose(new[]{old,faces},false,true).pid!=20)throw new Exception("2024 selected");Console.WriteLine("13/13 session selection tests PASS; no COM calls");return 0;}
}
